class Solution:
    def rotatedDigits(self, n: int) -> int:
        def good(x):
            changed = False
            while x:
                d = x % 10
                if d in (3, 4, 7):
                    return False
                if d in (2, 5, 6, 9):
                    changed = True
                x //= 10
            return changed
        return sum(good(x) for x in range(1, n + 1))

