class Solution {
public:
    int rotatedDigits(int n) {
        auto good = [](int x) {
            bool changed = false;
            while (x) {
                int d = x % 10;
                if (d == 3 || d == 4 || d == 7) return false;
                if (d == 2 || d == 5 || d == 6 || d == 9) changed = true;
                x /= 10;
            }
            return changed;
        };
        int cnt = 0;
        for (int x = 1; x <= n; ++x) if (good(x)) ++cnt;
        return cnt;
    }
};

