class Solution {
    public int rotatedDigits(int n) {
        int cnt = 0;
        for (int x = 1; x <= n; x++) {
            boolean changed = false, ok = true;
            for (int y = x; y > 0; y /= 10) {
                int d = y % 10;
                if (d == 3 || d == 4 || d == 7) { ok = false; break; }
                if (d == 2 || d == 5 || d == 6 || d == 9) changed = true;
            }
            if (ok && changed) cnt++;
        }
        return cnt;
    }
}

