class Solution {
public:
    int rotatedDigits(int n) {
        string s = to_string(n);
        int m = s.size();
        vector<vector<array<int,2>>> memo(m, vector<array<int,2>>(2, {-1,-1}));
        function<int(int,bool,bool)> dp = [&](int i, bool tight, bool changed) -> int {
            if (i == m) return changed ? 1 : 0;
            if (!tight && memo[i][changed][0] != -1) return memo[i][changed][0];
            int hi = tight ? s[i] - '0' : 9, total = 0;
            for (int d = 0; d <= hi; ++d) {
                if (d == 3 || d == 4 || d == 7) continue;
                total += dp(i + 1, tight && d == hi,
                            changed || d == 2 || d == 5 || d == 6 || d == 9);
            }
            if (!tight) memo[i][changed][0] = total;
            return total;
        };
        return dp(0, true, false);
    }
};

