class Solution {
    public int rotatedDigits(int n) {
        char[] s = Integer.toString(n).toCharArray();
        int m = s.length;
        Integer[][][] memo = new Integer[m][2][2];
        return dp(0, true, false, s, memo);
    }
    private int dp(int i, boolean tight, boolean changed, char[] s, Integer[][][] memo) {
        if (i == s.length) return changed ? 1 : 0;
        if (!tight && memo[i][changed ? 1 : 0] != null && memo[i][changed ? 1 : 0][changed ? 1 : 0] != null)
            return memo[i][changed ? 1 : 0][changed ? 1 : 0];
        int hi = tight ? s[i] - '0' : 9, total = 0;
        for (int d = 0; d <= hi; d++) {
            if (d == 3 || d == 4 || d == 7) continue;
            total += dp(i + 1, tight && d == hi,
                        changed || d == 2 || d == 5 || d == 6 || d == 9, s, memo);
        }
        if (!tight) memo[i][changed ? 1 : 0][changed ? 1 : 0] = total;
        return total;
    }
}

