class Solution:
    def rotatedDigits(self, n: int) -> int:
        def count(num, allowed):
            s = str(num)
            res = 0
            for i, ch in enumerate(s):
                d = int(ch)
                lower = sum(1 for a in allowed if a < d)
                res += lower * len(allowed) ** (len(s) - i - 1)
                if d not in allowed:
                    return res
            return res + 1
        v = {0, 1, 2, 5, 6, 8, 9}
        same = {0, 1, 8}
        return count(n, v) - count(n, same)

