class Solution {
public:
    long long countNum(long long num, const set<int>& allowed) {
        string s = to_string(num);
        long long res = 0;
        int m = s.size();
        for (int i = 0; i < m; ++i) {
            int d = s[i] - '0', lower = 0;
            for (int a : allowed) if (a < d) ++lower;
            long long p = 1;
            for (int j = 0; j < m - i - 1; ++j) p *= (long long)allowed.size();
            res += (long long)lower * p;
            if (!allowed.count(d)) return res;
        }
        return res + 1;
    }
    int rotatedDigits(int n) {
        set<int> v = {0,1,2,5,6,8,9}, same = {0,1,8};
        return (int)(countNum(n, v) - countNum(n, same));
    }
};

