class Solution {
    private long countNum(long num, int[] allowed) {
        String s = Long.toString(num);
        long res = 0;
        for (int i = 0; i < s.length(); i++) {
            int d = s.charAt(i) - '0', lower = 0;
            for (int a : allowed) if (a < d) lower++;
            long p = 1;
            for (int j = 0; j < s.length() - i - 1; j++) p *= allowed.length;
            res += (long) lower * p;
            boolean found = false;
            for (int a : allowed) if (a == d) found = true;
            if (!found) return res;
        }
        return res + 1;
    }
    public int rotatedDigits(int n) {
        int[] v = {0,1,2,5,6,8,9}, same = {0,1,8};
        return (int)(countNum(n, v) - countNum(n, same));
    }
}

